INSERT INTO `detail_categories` (`id`, `category_id`, `title`, `title_en`, `slug`, `description`, `description_en`, `img`, `created_at`, `updated_at`) VALUES
(4, 4, 'Antibiotik', 'Antibiotics', 'antibiotik', 'Antibiotik untuk tujuan apapun dalam peternakan, yang meliputi pengobatan pada saat sakit (terapeutik), pengobatan pada sekelompok hewan ketika setidaknya salah satu hewan terdiagnosis infeksi klinis (metafilaksis), dan pengobatan pencegahan (profilaksis).', 'Antibiotics for any purpose in animal husbandry, including treatment during illness (therapeutic), treatment of a group of animals when at least one of the animals is diagnosed with clinical infection (metaphylaxis), and preventive treatment (prophylaxis).', 'detail-category-images/01JVXX52A4PPX8S7ZD3HXAGEGG.png', '2025-05-22 23:26:41', '2025-07-10 00:27:24'),
(5, 5, 'Vitamin & Mineral', 'Vitamins & Minerals', 'vitamin-mineral', 'Kebutuhan mineral bagi ayam dalam masa produksi diperlukan sebagai bahan baku pembentukan isi dan kerabang telur. Kekurangan atau defisiensi mineral dapat menyebabkan dekomposisi organ tubuh ayam (seperti tulang) untuk memperoleh mineral.', 'Chickens need minerals during the production period as raw materials for the formation of egg contents and shells. Mineral deficiencies can cause the chicken\'s organs (such as bones) to decompose, preventing them from obtaining minerals.', 'detail-category-images/01JVXX8T7MT35R6JDHAEK4BJCH.png', '2025-05-22 23:28:43', '2025-07-10 00:31:46'),
(6, 7, 'Antikoksidia', 'Anti Coccidia', 'anti-coccidia', 'Penyakit pencernaan yang disebabkan oleh protozoa parasit Genus Eimeria. Eimeria yang menyerang unggas terdiri atas sembilan jenis, enam diantaranya sangat patogen menyerang ayam.', 'A digestive disease caused by parasitic protozoa of the genus Eimeria. There are nine species of Eimeria that infect poultry, six of which are highly pathogenic in chickens.', 'detail-category-images/01JVXXC2GW58N920PWJF7NGHQ3.png', '2025-05-22 23:30:30', '2025-07-10 00:37:36'),
(7, 8, 'Antiparasit', 'Antiparasitic', 'antiparasit', 'Obat antiparasit adalah sekelompok obat yang digunakan dalam pengelolaan dan pengobatan infeksi parasit, termasuk protozoa, cacing, dan ektoparasit. Obat antiparasit mencakup beberapa golongan obat yang mencakup berbagai macam penyakit yang disebabkan oleh parasit.', 'Antiparasitic drugs are a group of medications used in the management and treatment of parasitic infections, including protozoa, helminths (worms), and ectoparasites. These drugs encompass several classes of medications that cover a wide range of diseases caused by parasites.', 'detail-category-images/01JVXXHHFYMDMB2037PZ1RHJKY.png', '2025-05-22 23:33:29', '2025-07-10 00:33:34'),
(8, 9, 'Disinfektan', 'Disinfectant', 'disinfektan', 'Sebagai salah satu bentuk pencegahan penyebaran penyakit mulut dan kuku pada hewan ternak sapi dan kambing maka perlu di lakukan disinfektasi sekitar kandang ternak, baik kandang kelompok maupun perorangan.', 'As a form of preventing the spread of foot and mouth disease in cattle and goats, it is necessary to disinfect the area around livestock pens, both group and individual pens.', 'detail-category-images/01JVXXMK65WTVT4STZPJ9R3VVE.png', '2025-05-22 23:35:09', '2025-07-10 00:33:42'),
(9, 10, 'Premix', 'Premix', 'premix', 'Premix untuk pakan ternak dapat membantu hewan Anda menghasilkan susu dan daging sapi berkualitas, mendukung mereka melalui berbagai tahap pertumbuhan, serta meningkatkan kesehatan dan kekebalan mereka. Selain itu, jika ternak Anda menerima semua nutrisi yang tepat, hal ini dapat membantu mengurangi konsumsi pakan.', 'Premixed animal feed can help your animals produce quality milk and beef, support them through various stages of growth, and improve their health and immunity. Furthermore, providing your animals with all the proper nutrients can help reduce feed consumption.', 'detail-category-images/01JVXXVRBCVD6DMJ62HKB2E32K.png', '2025-05-22 23:39:04', '2025-07-10 00:34:05'),
(10, 11, 'Akuatik', 'Aquatic', 'akuatik', 'Berperan sebagai penyusun utama struktur rangka pada udang, misalnya cangkang, tulang, dan gigi. Berperan mendorong pembentukan kulit baru pada udang.', 'It plays a major role in the skeletal structure of shrimp, such as shells, bones, and teeth. It also promotes the formation of new skin in shrimp.', 'detail-category-images/01JVXXY8N4X0CBEK5WFDVHMSM6.png', '2025-05-22 23:40:26', '2025-07-10 00:34:46'),
(11, 12, 'Produk PMK', 'PMK Products', 'produk-pmk', 'Penyakit Mulut dan Kuku (PMK) merupakan penyakit viral yang sangat menular dan menyerang semua hewan berkuku belah/genap. Seperti, sapi, kerbau, babi.', 'Foot and Mouth Disease (FMD) is a viral disease that is very contagious and attacks all animals with cloven/even hooves. Such as cows, buffalo, pigs.', 'detail-category-images/01JVXY2VXHAPRFDA9DM7AZ3S09.png', '2025-05-22 23:42:57', '2025-07-10 00:35:47');

