--
-- Struktur dari tabel `products`
--

CREATE TABLE `products` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `detail_category_id` bigint(20) UNSIGNED NOT NULL,
  `name` varchar(255) NOT NULL,
  `name_en` varchar(255) DEFAULT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `list_image` varchar(255) NOT NULL,
  `image_top` varchar(255) NOT NULL,
  `image_top_en` varchar(255) DEFAULT NULL,
  `image_bottom` varchar(255) DEFAULT NULL,
  `image_bottom_en` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `alt_top` text DEFAULT NULL,
  `alt_top_en` text DEFAULT NULL,
  `alt_bottom` text DEFAULT NULL,
  `alt_bottom_en` text DEFAULT NULL,
  `aktif` tinyint(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

