INSERT INTO `products` (`id`, `detail_category_id`, `name`, `name_en`, `slug`, `list_image`, `image_top`, `image_top_en`, `image_bottom`, `image_bottom_en`, `created_at`, `updated_at`, `alt_top`, `alt_top_en`, `alt_bottom`, `alt_bottom_en`, `aktif`) VALUES
(6, 4, 'CYPROTIL', 'CYPROTIL', 'cyprotil', 'products/01JZ06QKVXMQDRDN5Y1KH0CQK2.jpg', 'products/01JWM9MPB8Z3SVQ5455DCFKZRD.png', 'products/01JZSK0RQ2X0H5H76T1PT7MC9Y.jpg', 'products/01JWM9MPBBHTPAQ1H9DG24AMVH.png', 'products/01JZSK0RQ55S3VQP3VJ5VMGXNZ.jpg', '2025-05-31 16:08:13', '2025-07-26 05:16:54', 'CYPROTIL®\nObat CRD Kompleks\nKementan RI: No. D.16075123 PKS\n\nEfektif mengobati:\nCRD Kompleks\n\nColibacillosis\n\nPullorum (berak kapur)\n\nCoryza / snot (muka bengkak)\n\nCholera (berak hijau)\n\nStaphylococcus\n\nSalmonellosis\n\nPT. SATWA MEDIKA UTAMA\nSADITA\nProdusen & Distributor Obat Hewan\n\nJalan Raya Serpong, Komplek Pergudangan\nBizhub Blok GF No 6, Gunung Sindur, Bogor,\nJawa Barat – Indonesia |\nTelepon: 0811444842\nWebsite: https://saditaindonesia.co.id', 'CYPROTIL®\nCRD Complex Medication\nMinistry of Agriculture of the Republic of Indonesia: No. D.16075123 PKS\n\nEffective in treating:\nCRD Complex\n\nColibacillosis\n\nPullorum (chalky stools)\n\nCoryza/snot (swollen face)\n\nCholera (green stools)\n\nStaphylococcus\n\nSalmonellosis\n\nPT. SATWA MEDIKA UTAMA\nSADITA\nVeterinary Medicine Manufacturer & Distributor\n\nJalan Raya Serpong, Warehouse Complex\nBizhub Block GF No. 6, Gunung Sindur, Bogor,\nWest Java – Indonesia |\nPhone: 0811444842\nWebsite: https://saditaindonesia.co.id', 'CYPROTIL®\nObat CRD Kompleks\n\nINDIKASI\nEfektif mengobati CRD Kompleks, Colibacillosis, Pullorum (berak kapur), Coryza/snot (muka bengkak), Cholera (berak hijau), Staphylococcus dan Salmonellosis\n\nKOMPOSISI\nSetiap 1Kg mengandung:\nCiprofloxacin ..................................................................... 125 gram\n\nCARA KERJA OBAT\nCiprofloxacin merupakan salah satu obat sintetik derivat quinolone. Mekanisme kerjanya adalah menghambat aktifitas DNA gyrase bakteri, bersifat bakterisida spektrum luas terhadap bakteri gram positif maupun gram negatif.\n\nDOSIS DAN ATURAN PAKAI\nUnggas: 0,1 gram per kg berat badan atau 1 gram per 2 liter air minum, diberikan selama 3–5 hari berturut-turut\n\nPENYIMPANAN\nSimpan di tempat kering dan terhindar cahaya matahari\n\nKEMASAN\n50, 100 dan 250 gram', 'CYPROTIL®\nComplex CRD Medication\n\nINDICATIONS\nEffective in treating complex CRD, colibacillosis, pullorum (chalky stools), coryza (swollen face), cholera (green stools), staphylococcus, and salmonellosis.\n\nCOMPOSITION\nEach 1 kg contains:\nCiprofloxacin ................................................................................... 125 grams\n\nHOW THE DRUG WORKS\nCiprofloxacin is a synthetic quinolone derivative. Its mechanism of action is by inhibiting bacterial DNA gyrase activity, providing a broad-spectrum bactericidal effect against both gram-positive and gram-negative bacteria.\n\nDOSAGE AND DIRECTIONS FOR USE\nPoultry: 0.1 gram per kg of body weight or 1 gram per 2 liters of drinking water, given for 3–5 consecutive days.\n\nSTORAGE\nStore in a dry place, away from sunlight.\n\nPACKAGING\n50, 100, and 250 grams', 1),
(7, 4, 'DITA FLOXA LIQ', 'DITA FLOXA LIQ', 'dita-floxa-liq', 'products/01JZ06RRR7G3S584FMX53YQZW7.jpg', 'products/01JWM9VX0RPKSYFP1A3SM2XP7S.png', 'products/01JZVHFCD18GFV8Y4ZBM2V43KA.jpg', 'products/01JWM9VX0TYMG83QR55D7YV8V7.png', 'products/01JZVHFCD5JC9HCWG03RWFFXN2.jpg', '2025-05-31 16:12:09', '2025-07-18 23:16:45', 'DITA FLOXA LIQ®\nObat CRD Kompleks\nKementan RI: No. D.21036820PKC\n\nEfektif Mengobati:\nCRD Kompleks\n\nColibacillosis\n\n Coryza\n\nCholera.\n\nPT. SATWA MEDIKA UTAMA\nSADITA\nProdusen dan distributor Obat Hewan\n\nJalan Raya Serpong, Komplek Pergudangan \nBizhub Blok GF No 6, Gunung Sindur, Bogor, \nJawa Barat - Indonesia | Telepon: 0811444842\nWebsite: https://saditaindonesia.co.id', 'DITA FLOXA LIQ®\nKementan RI: No. D.21036820PKC\n\nEffectively treats:\nCRD Complex\n\nColibacillosis\n\nCoryza\n\nCholera\n\nPT. SATWA MEDIKA UTAMA\nHighway Serpong, Warehouse Complex Bizhub\nBlok GF No 6, Gunung Sindur, Bogor, Jawa Barat - Indonesia\nTelephone: 0811444842\nWebsite: https://saditaindonesia.co.id', 'DITA FLOXA LIQ®\nObat CRD Kompleks\n\nINDIKASI:\nEfektif mengobati CRD Kompleks, Colibacillosis,\nCoryza dan Cholera.\n\nKOMPOSISI:\nSetiap 1 kg mengandung: \nEnrofloxacin .............................................................. 100 gram\nSorbitol ...................................................................... 260 gram\nNipagin ........................................................................ 2,5 gram\nAquadest .................................................................. 1000 gram\n\nCARA KERJA OBAT:\nMembasmi bakteri. Daya kerjanya adalah berdasarkan \nhambatan terhadap enzim DNA gyraze yang diperlukan \nuntuk pembelahan inti sel bakteri. Enrofloxacin suatu \nantibakteri derivat Fluoroquinolon yang bekerja luas \nefektif membasmi Mycoplasma sp., E-Coli, Haemophilus \nParagallinarum dan Pasteurella Multocida.\n\nDOSIS DAN ATURAN PAKAI:\nUnggas: 0,1 gram per kg berat badan atau 1 gram per 2 \nliter air minum, diberikan selama 3-5 hari berturut-turut.\n\nPENYIMPANAN:\nSimpan di tempat kering dan terhindar cahaya matahari\n\nKEMASAN:\n100 Ml, 500 Ml, & 1 L', 'DITA FLOXA LIQ®\nCRD Complex Drugs\n\nINDICATION:\nEffectively treats CRD complex, colibacillosis, coryza, and cholera.\n\nCOMPOSITION:\nEach 1 kg contains:\nEnrofloxacin ............................................................ 100 grams\nSorbitol .................................................................... 260 grams\nNipagin ...................................................................... 2.5 grams\nAquadest ................................................................ 1000 grams\n\nHOW THE DRUG WORKS:\nEradicate bacteria. Its working power is based on the inhibition of the DNA gyrase enzyme necessary for the division of the bacterial cell nucleus. Enrofloxacin, an antibacterial fluoroquinolone derivative that works widely effectively against Mycoplasma sp., E. coli, Haemophilus paragallinarum, and Pasteurella multocida.\n\nDOSAGE AND DIRECTION OF USE:\nPoultry: 0.1 grams per kg of body weight or 1 gram per 2 liters of drinking water, the treatment is given for 3–5 days in a row.\n\nSTORAGE:\nStore in a dry place and protected from sunlight.\n\nPACKAGING:\n100 mL, 500 mL, & 1 L', 1),
(8, 4, 'DITA FLOXA POWDER', 'DITA FLOXA POWDER', 'dita-floxa-powder', 'products/01JZ06SCP9CAQASHVRZ2XE77KY.jpg', 'products/01JWM9YB27C1BTXVAB9MSVQH8V.png', 'products/01JZVHG6QGZSFXP5SGNXAB4TYW.jpg', 'products/01JWM9YB2A7MA87025QQBGXFEA.png', 'products/01JZVHG6QMFGAWMJF1DHWRQT5C.jpg', '2025-05-31 16:13:29', '2025-12-08 17:24:17', 'DITA FLOXA POWDER®\nObat CRD Komleks\nKementan RI: No. D.16095141 PKS\n\nEfektif Mengobati:\nCRD Kompleks\n\nColibacillosis\n\nCoryza\n\nCholera\n\nPT. SATWA MEDIKA UTAMA\nSADITA\nProdusen & Distributor Obat Hewan\n\nJalan Raya Serpong, Komplek Pergudangan \nBizhub Blok GF No 6, Gunung Sindur, Bogor, \nJawa Barat - Indonesia | Telepon: 0811444842\nWebsite: https://sadita.id', 'DITA FLOXA POWDER®\nCRD Complex Drugs\n\nEffectively treats:\nCRD Complex\n\nColibacillosis\n\nCoryza\n\nCholera\n\nPT. SATWA MEDIKA UTAMA\nHighway Serpong, Warehouse Complex Bizhub\nBlok GF No 6, Gunung Sindur, Bogor, Jawa Barat - Indonesia\nTelephone: 0811444842\nWebsite: https://sadita.id', 'DITA FLOXA POWDER®\nObat CRD Kompleks\n\nINDIKASI:\nEfektif mengobati CRD Kompleks, Colibacillosis,\nCoryza dan Cholera.\n\nKOMPOSISI:\nSetiap 1 kg mengandung: \nEnrofloxacin .............................................................. 100 gram\n\nCARA KERJA OBAT:\nMembasmi bakteri. Daya kerjanya adalah berdasarkan \nhambatan terhadap enzim DNA gyraze yang diperlukan \nuntuk pembelahan inti sel bakteri. Enrofloxacin suatu \nantibakteri derivat Fluoroquinolon yang bekerja luas \nefektif membasmi Mycoplasma sp., E-Coli, Haemophilus \nParagallinarum dan Pasteurella Multocida.\n\nDOSIS DAN ATURAN PAKAI:\nUnggas: 0,1 gram per kg berat badan atau 1 gram per 2 \nliter air minum, diberikan selama 3-5 hari berturut-turut\n\nPENYIMPANAN:\nSimpan di tempat kering dan terhindar cahaya matahari\n\nKEMASAN:\n500 gr, 250 gr, & 100 g', 'DITA FLOXA LIQ®\nCRD Complex Drugs\n\nINDICATION:\nEffectively treats complex CRD, colibacillosis, coryza and cholera.\n\nCOMPOSITION:\nEach 1 kg contains:\nEnrofloxacin ............................................................. 100 grams\n\nHOW THE DRUG WORKS:\nEradicate bacteria. Its working power is based on the inhibition of the DNA gyrase enzyme necessary for the division of the bacterial cell nucleus. Enrofloxacin is an antibacterial derivative. Widely acting fluoroquinolones effectively eradicate Mycoplasma sp., E. coli, Haemophilus paragallinarum and Pasteurella multocida.\n\nDOSAGE AND DIRECTION OF USE:\nPoultry: 0.1 grams per kg of body weight or 1 gram/2 liters of drinking water, the treatment is given for 3–5 days in a row.\n\nSTORAGE:\nStore in a dry place and protected from sunlight\n\nPACKAGING:\n500 gr, 250 gr, & 100 gr', 1),
(9, 4, 'DITA THERAPIX', 'DITA THERAPIX', 'dita-therapix', 'products/01JZ06T3YNH0DCBFXH95XS5YRP.jpg', 'products/01JWMA1R50YHZ1V3WWFQSSGFT2.png', 'products/01JZVHGXKSPJYPPTXRQ38FDY2K.jpg', 'products/01JWMA1R53XDYW9YCZ2M9HSGS7.png', 'products/01JZVHGXKWJB2H2TTC74GMS60A.jpg', '2025-05-31 16:15:21', '2025-07-18 23:45:31', 'DITA THERAPIX®\nObat Kolera dan Coccidiosis\nKementan RI: No. D.240272475PKS\n\nEfektif Mengobati:\nKolera (berak Hijau)\n\nCoccidiosis (berak darah)\n\nPT. SATWA MEDIKA UTAMA \nSADITA\nProdusen & Distributor Obat Hewan\n\nJalan Raya Serpong, Komplek Pergudangan \nBizhub Blok GF No 6, Gunung Sindur, Bogor, \nJawa Barat - Indonesia | Telepon: 0811444842\nWebsite: https://saditaindonesia.co.id', 'DITA THERAPIX®\nCholera and Coccidiosis Drugs \nKementan RI: No. D.240272475PKS\n\nPrevention and treatment of Coccidiosis, Cholera, Pullorum, Coryza, Colibacillosis and Synovitis.\n\nPT. SATWA MEDIKA UTAMA\nHighway Serpong, Warehouse Complex Bizhub\nBlok GF No 6, Gunung Sindur, Bogor, Jawa Barat - Indonesia\nTelephone: 0811444842\nWebsite: https://saditaindonesia.co.id', 'DITA THERAPIX®\nObat Kolera dan Coccidiosis\n\nINDIKASI:\nMencegah dan pengobatan terhadap Coccidiosis \n(berak darah), Kolera (berak hijau), Pullorum (Berak \nKapur), Coryza, Colibacillosis dan Synovitis.\n\nKOMPOSISI:\nSetiap 1 kg mengandung: \nOxytetracycline HCI ........................................................ 125 gr \n Amprolium ........................................................................ 50 gr\n\nCARA KERJA OBAT:\nOxytetracycline adalah bakteriostatik dan dalam \nkonsentrasi tinggi adalah bakteriosid. Cara kerja \nkelompok antibiotik tetraskilin adalah dengan \nmenghambat sintesis protein mikroorganisme. \nAmprolium sebagai obat koksidosis golongan thiamine \nantagonis sangat efektif untuk mengatasi instetinal \ncocodia\n\nDOSIS DAN ATURAN PAKAI:\nUnggas: 0,1 gram per kg berat badan atau 1 gram per 2 \nliter air minum, diberikan selama 3-5 hari berturut-turut\n\nPENYIMPANAN:\nSimpan di tempat kering dan terhindar cahaya matahari\n\nKEMASAN:\n250 dan 100 gram', 'DITA THERAPIX®\nCholera and Coccidiosis Drugs \n\nINDICATION:\nPrevention and treatment of coccidiosis, cholera, pullorum disease, coryza, colibacillosis, and synovitis.\n\nCOMPOSITION:\nEach 1 kg contains:\nOxytetracycline HCl ........................................................ 125 gr\nAmprolium ......................................................................... 50 gr\n\nHOW THE DRUG WORKS:\nOxytetracycline is bacteriostatistical and in high concentration is bacterioside. The way tetrasklin antibiotic group works is by inhibiting the protein synthesis of microorganisms. Amprolium as a coccidiosis drug of the thiamine antagonist group is very effective to overcome intestinal coccidia.\n\nDOSAGE AND DIRECTION OF USE:\nPoultry: 0.1 grams per kg of body weight or 1 gram per 2 liters of drinking water, the treatment is given for 3–5 days in a row.\n\nSTORAGE:\nStore in a dry place and protected from sunlight.\n\nPACKAGING:\n250 grams and 100 grams', 1),
(10, 4, 'DOXYTHRO', 'DOXYTHRO', 'doxytrhro', 'products/01JZ06TTXQ8A558AYKNBM62769.jpg', 'products/01JWMAEG85RQ109XN1ZJY47F6Q.png', 'products/01JZVHHK8VF1GEC3C21TAZ0H3F.jpg', 'products/01JWMAEG873SJ5XYVKJAFT85VD.png', 'products/01JZVHHK8Y7GJSG5ZEDKMKPRVW.jpg', '2025-05-31 16:22:19', '2025-12-02 18:39:04', 'DOXYTHRO®\nObat CRD Kompleks\nKementan RI: No. D.15034971PKS\n\nUntuk pengobatan:\nCRD kompleks\n\nCoryza/Snot\n\nColibacillosis\n\nFowl Cholera\n\nSalmonellosis\n\nFowl Typhoid\n\nParatyphoid pada Unggas\n\nPT. SATWA MEDIKA UTAMA\nSADITA\nProdusen & Distributor Obat Hewan\n\nJalan Raya Serpong, Komplek Pergudangan \nBizhub Blok GF No 6, Gunung Sindur, Bogor, \nJawa Barat - Indonesia | Telepon: 0811444842\nWebsite: https://saditaindonesia.co.id', 'DOXYTHRO®\nCRD Complex Drugs\nKementan RI: No. D.15034971PKS\n\nFor the treatment of complex CRD\nCoryza/Snot\n\nColibacillosis\n\nFowl Cholera\n\nSalmonellosis\n\nFowl Typhoid\n\nParatyphoid in Poultry.\n\nPT. SATWA MEDIKA UTAMA\nHighway Serpong, Warehouse Complex Bizhub\nBlok GF No 6, Gunung Sindur, Bogor, Jawa Barat - Indonesia\nTelephone: 0811444842\nWebsite: https://saditaindonesia.co.id', 'DOXYTHRO®\nObat CRD Kompleks\n\nINDIKASI:\nUntuk pengobatan CRD kompleks, Coryza/Snot, \nColibacillosis, Fowl Cholera, Salmonellosis, Fowl \nTyphoid dan Paratyphoid pada Unggas\n\nKOMPOSISI:\nSetiap 1 kg mengandung: \nDoksisiklin ................................................................ 100 gram\nEritromisin ............................................................... 200 gram\n\nCARA KERJA OBAT:\nDoxycycline adalah antibiotik golongan tetrasiklin. \nDoxycycline bekerja secara bakteriostatik dengan \nmencegah sintesa protein mikroorganisme. Doxycycline \nmempunyai spektrum kerja yang luas terhadap bakteri \ngram positif dan gram negatif. Gabungan dengan \nErythromycin akan lebih efektif membunuh bakteri \ntersebut\n\nDOSIS DAN ATURAN PAKAI:\nUnggas: 1 gram per 2 liter air minum atau 0,1 gram per kg \nberat badan, diberikan selama 3-5 hari berturut-turut\n\nPENYIMPANAN:\nSimpan di tempat kering dan terhindar cahaya matahari\nP\n\nKEMASAN:\n100 gr, 250 gr, & 1 Kg', 'DOXYTHRO®\nCRD Complex Drugs\n\nINDICATION:\nFor the treatment of complex CRD, coryza/snot, colibacillosis, fowl cholera, salmonellosis, fowl typhoid, and paratyphoid in poultry.\n\nCOMPOSITION:\nEach 1 kg contains:\nDoxycycline ..................................................................... 100 grams\nErythromycin ................................................................... 200 grams\n\nHOW THE DRUG WORKS:\nDoxycycline is a tetracycline class of antibiotics. Doxycycline works bacteriostatically by preventing the protein synthesis of microorganisms. Doxycycline has a broad spectrum of action against gram-positive and gram-negative bacteria. Combined with Erythromycin it will be more effective in killing these bacteria.\n\nDOSAGE AND DIRECTION OF USE:\nPoultry: 1 gram per 2 liters of drinking water or 0.1 gram per kg body weight, the treatment is given for 3–5 consecutive days.\n\nSTORAGE:\nStore in a dry place and protected from sunlight.\n\nPACKAGING:\n100 gr, 250 gr, & 1 Kg', 1),
(11, 4, 'KOLERIN', 'KOLERIN', 'kolerin', 'products/01JZ06XDVYPMD6F3DJNCCC9G5V.jpg', 'products/01JWMAG95AMNVM80EJDX7SXHB8.png', 'products/01JZVHJFFXHD0C46S1WK04H7GZ.jpg', 'products/01JWMAG95DP4RHE70B6NJ0ZJGM.png', 'products/01JZVHJFG0PVAZKARN1BSQ6ACF.jpg', '2025-05-31 16:23:17', '2025-07-19 00:28:10', 'KOLERIN®\nObat Kolera/Berak Hijau\nKementan RI: No. D.16095142PKS\n\nUntuk pengobatan penyakit:\nsaluran pencernaan terutama yang\ndisebabkan oleh bakteri Pasteurella\n\nSalmonella & E-coli\n\nPT. SATWA MEDIKA UTAMA \nSADITA\nProdusen & Distributor Obat Hewan\n\nJalan Raya Serpong, Komplek Pergudangan \nBizhub Blok GF No 6, Gunung Sindur, Bogor, \nJawa Barat - Indonesia | Telepon: 0811444842\nWebsite: https://saditaindonesia.co.id', 'KOLERIN®\nGreen Cholera/Stool Medicine\nKementan RI: No. D 16095142 PKS\n\nFor the treatment of digestive tract diseases, especially those caused by Pasteurella, Salmonella & E-coli bacteria.\n\nPT. SATWA MEDIKA UTAMA\nHighway Serpong, Warehouse Complex Bizhub\nBlok GF No 6, Gunung Sindur, Bogor, Jawa Barat - Indonesia\nTelephone: 0811444842\nWebsite: https://saditaindonesia.co.id', 'KOLERIN®\nObat Kolera/Berak Hijau\n\nINDIKASI:\nUntuk pengobatan penyakit saluran pencernaan \nterutama yang disebabkan oleh bakteri Pasteurella, \nSalmonella & E-coli\n\nKOMPOSISI:\nSetiap 1 gram mengandung: \nOxytetracycline ............................................................ 100 mg\nNeomycin ........................................................................ 75 mg\n\nCARA KERJA OBAT:\nOxytetracycline adalah antibiotik spektrum luas dan \naktif melawan bakteri gram positif, gram negatif dan \nbakteri anaerob. Oxytetracycline menghambat sintesa \ndinding sel bakteri dengan menghambat aktifitas \nenzyme transpeptidase yang mengkatalisa ikatan silang \nglikopeptida polimer unit yang membentuk dinding sel. \nAntibiotik neomycin secara langsung melawan bakteri \nanaerob gram negatif seperti E-coli, Salmonella dan \nStaphylococcus aureus\n\nDOSIS DAN ATURAN PAKAI:\nUnggas: 1 gram per 2 liter air minum atau 0,1 gram per kg \nberat badan, diberikan selama 3-5 hari berturut-turut\n\nPENYIMPANAN:\nSimpan di tempat kering dan terhindar cahaya matahari\n\nKEMASAN:\n100 gr, 250 gr, & 500 gram', 'KOLERIN®\nGreen Cholera/Stool Medicine\n\nNDICATION:\nFor the treatment of digestive tract diseases, especially those caused by Pasteurella, Salmonella & E-coli bacteria.\n\nCOMPOSITION:\nEvery 1 gram contains:\nOxytetracycline ............................................................ 100 mg\nNeomycin ........................................................................ 75 mg\n\nHOW THE DRUG WORKS:\nOxytetracycline is a broad spectrum antibiotic and is active against gram-positive, gram-negative and anaerobic bacteria. Oxytetracycline inhibits bacterial cell wall synthesis by inhibiting the activity of the transpeptidase enzyme which catalyzes the cross-linking of glycopeptide polymer units that form cell walls. Neomycin antibiotics directly fight gram-negative anaerobic bacteria such as E. coli, Salmonella and Staphylococcus aureus.\n\nDOSAGE AND DIRECTION OF USE:\nPoultry: 1 gram per 2 liters of drinking water or 0.1 gram per kg body weight, the treatment is given for 3–5 consecutive days.\n\nSTORAGE:\nStore in a dry place and protected from sunlight.\n\nPACKAGING: \n100, 250, & 500 grams', 1),
